//
// The port, checked against the thing it was ported from.
//
// Fixtures/progression.json was generated by running the web app's own
// lib/engine.ts over 210 combinations of lift, level and history, and keeping
// what it answered. If the Swift rules disagree with it on any one of them,
// the port drifted, and this says which case and in which direction.
//
// Regenerate it from the web repo when a rule is deliberately changed, and
// say so in the commit. Until then, the web app is the specification.

import XCTest
@testable import HabitaBullKit

private struct Case: Decodable {
    let lift: String, level: String, shape: String
    let increment: Double, compound: Bool, heavy: Bool, hold: Bool, cardio: Bool
    let history: [[Pair]]
    let weight: Double, reps: Int, sets: Int, note: String

    struct Pair: Decodable { let weight: Double; let reps: Int }
}

final class PortParityTests: XCTestCase {
    func testEveryAnswerMatchesTheWebEngine() throws {
        let url = try XCTUnwrap(Bundle.module.url(forResource: "progression", withExtension: "json"),
                                "the fixture is missing from the test bundle")
        let cases = try JSONDecoder().decode([Case].self, from: Data(contentsOf: url))
        XCTAssertGreaterThan(cases.count, 100, "the fixture looks truncated")

        var drifted: [String] = []
        for c in cases {
            let lift = LiftShape(increment: c.increment, compound: c.compound,
                                 heavy: c.heavy, hold: c.hold, cardio: c.cardio)
            let history = c.history.map { $0.map { DoneSet(weight: $0.weight, reps: $0.reps) } }
            let got = Progression.next(lift, history: history, level: Level(rawValue: c.level)!)
            let where_ = "\(c.lift) · \(c.level) · \(c.shape)"
            if abs(got.weight - c.weight) > 0.0001 { drifted.append("\(where_): weight \(got.weight) vs \(c.weight)") }
            if got.reps != c.reps { drifted.append("\(where_): reps \(got.reps) vs \(c.reps)") }
            if got.sets != c.sets { drifted.append("\(where_): sets \(got.sets) vs \(c.sets)") }
            if got.note != c.note { drifted.append("\(where_): note \"\(got.note)\" vs \"\(c.note)\"") }
        }
        XCTAssertEqual(drifted, [], "the Swift rules answer differently from the web engine")
    }
}
